import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine().trim());
        String[] parts = scanner.nextLine().trim().split("\\s+");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(parts[i]);
        }

        Arrays.sort(a);

        double avr = 0;
        for (int i = 0; i < n; i++) {
            avr += a[i];
        }
        avr = avr / n;

        if (avr - 4.5 >= 0) {
            System.out.println(0);
        } else {
            double num = 4.5 - avr;
            num = num * n;
            if (Math.abs((int) num - num) > 0.0000001) {
                num = Math.ceil(num);
            } else {
                num = (int) num;
            }
            int cnt = 0;
            for (int i = 0; i < n; i++) {
                num += a[i] - 5;
                cnt += 1;
                if (num <= 0) {
                    break;
                }
            }
            System.out.println(cnt);
        }
    }
}

